head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil40207";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil40207.onpageload' });
    }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "ipt_fssUnqNo", fn: function () { return String(String((dma_pageContext.get("fssUnqNo") ?? ""))); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name slc_selEmail_onchange
 * @description slc_selEmail 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.slc_selEmail_onchange = function(e){
    try {
        ((s, t) => { if (t && t.setValue) { t.setValue((s && s.getValue) ? s.getValue() : ""); } const i = (s && typeof s.getSelectedIndex === "function") ? s.getSelectedIndex() : -1; if (i === 0 && t && t.focus) { t.focus(); } })($c.util.getComponent("slc_selEmail"), $c.util.getComponent('ipt_email2'));

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil40207.slc_selEmail_onchange' }); }
};

/**
 * @method
 * @name btn_ApplyJoin_onclick
 * @description 「가입신청」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_ApplyJoin_onclick = async function(e){
    try {
        await scwin.applyJoin()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil40207.btn_ApplyJoin_onclick' }); }
};

/**
 * @method
 * @name btn_GoURL_onclick
 * @description 「취소」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_GoURL_onclick = function(e){
    try {
        scwin.goURL('cancel')

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil40207.btn_GoURL_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_ApplyJoin
 * @description Apply Join 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_ApplyJoin = async function (action) {
    const sbmOptions = {
        id: "tx_fn_ApplyJoin",
        method: "post",
        action: action ?? "/register/votediscls.do",
        ref: "dma_ApplyJoinReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name goURL
 * @description go URL 처리
 * @param {*} _target _target
 * @returns {void}
 * @hidden N
 */
scwin.goURL = function (_target) {
    let linkUrl;
    if (_target === 'cancel') {
        linkUrl = '/';
    }
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    $c.win.setPageFrameSrc($c.win.getFrame(), (function (__u) { const __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(linkUrl));
};

/**
 * @method
 * @name applyJoin
 * @description apply Join 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.applyJoin = async function () {
    if (($c.util.getComponent('ipt_fssUnqNo').getValue() == null ? '' : String($c.util.getComponent('ipt_fssUnqNo').getValue())) === '') {
        await $c.win.alert('금감원 고유코드가 없으면 신규가입하실 수 없습니다. 시스템담당자(02-3774-9572,9573)에게 문의하세요.');
        return;
    }
    if (await $c.fil.checkRequired($c.util.getComponent('ipt_corpRegNo'))) {
        return;
    }
    if ($c.util.getComponent('ipt_corpRegNo').getValue().length !== 13) {
        await $c.win.alert(((__a) => ((__a && __a.getAttribute) ? ((__a.getAttribute("alt") || __a.getAttribute("toolTip") || (__a.getTitle ? (__a.getTitle() ?? "") : "")) || "") : (__a ? (__a.alt ?? "") : "")))($c.util.getComponent('ipt_corpRegNo')) + '는 13자리입니다.');
        return;
    }
    if ($c.util.getComponent('ipt_corpRegNo').getValue().length !== 13) {
        await $c.win.alert(((__a) => ((__a && __a.getAttribute) ? ((__a.getAttribute("alt") || __a.getAttribute("toolTip") || (__a.getTitle ? (__a.getTitle() ?? "") : "")) || "") : (__a ? (__a.alt ?? "") : "")))($c.util.getComponent('ipt_corpRegNo')) + '는 13자리입니다.');
        $c.util.getComponent("ipt_corpRegNo").focus();
        return;
    }
    if (await $c.fil.checkRequired($c.util.getComponent('ipt_bzRegNo'))) {
        return;
    }
    if ($c.util.getComponent('ipt_bzRegNo').getValue().length !== 10) {
        await $c.win.alert(((__a) => ((__a && __a.getAttribute) ? ((__a.getAttribute("alt") || __a.getAttribute("toolTip") || (__a.getTitle ? (__a.getTitle() ?? "") : "")) || "") : (__a ? (__a.alt ?? "") : "")))($c.util.getComponent('ipt_bzRegNo')) + '는 10자리입니다.');
        $c.util.getComponent("ipt_bzRegNo").focus();
        return;
    }
    if (!($c.fil.isNumberInput($c.util.getComponent('ipt_bzRegNo')))) {
        await $c.win.alert('사업자등록번호는 숫자만 입력하세요');
        return;
    }
    if (await $c.fil.checkRequired($c.util.getComponent('ipt_corpNm'))) {
        return;
    }
    if (await (async (c) => { const v = String((c && c.getValue) ? (c.getValue() ?? "") : ""); const max = Number((c && c.getUserData) ? ((c.getUserData("maxByteLength") || c.getUserData("maxLength")) ?? 0) : 0) || 0; if (max && $c.str.getByteLength(v) > max) { const lbl = "회사명"; await $c.win.alert((lbl ? ("'" + lbl + "' 항목은 ") : "") + "한글 " + (max / 2) + "자, 영문 " + max + "자까지 가능합니다."); return true; } return false; })($c.util.getComponent('ipt_corpNm'))) {
        return;
    }
    if (await $c.fil.checkRequired($c.util.getComponent('ipt_corpAbbrv'))) {
        return;
    }
    if (await (async (c) => { const v = String((c && c.getValue) ? (c.getValue() ?? "") : ""); const max = Number((c && c.getUserData) ? ((c.getUserData("maxByteLength") || c.getUserData("maxLength")) ?? 0) : 0) || 0; if (max && $c.str.getByteLength(v) > max) { const lbl = "회사약명"; await $c.win.alert((lbl ? ("'" + lbl + "' 항목은 ") : "") + "한글 " + (max / 2) + "자, 영문 " + max + "자까지 가능합니다."); return true; } return false; })($c.util.getComponent('ipt_corpAbbrv'))) {
        return;
    }
    if (await $c.fil.checkRequired($c.util.getComponent('ipt_corpEngNm'))) {
        return;
    }
    if (await (async (c) => { const v = String((c && c.getValue) ? (c.getValue() ?? "") : ""); const max = Number((c && c.getUserData) ? ((c.getUserData("maxByteLength") || c.getUserData("maxLength")) ?? 0) : 0) || 0; if (max && $c.str.getByteLength(v) > max) { const lbl = "회사영문명"; await $c.win.alert((lbl ? ("'" + lbl + "' 항목은 ") : "") + "한글 " + (max / 2) + "자, 영문 " + max + "자까지 가능합니다."); return true; } return false; })($c.util.getComponent('ipt_corpEngNm'))) {
        return;
    }
    if (await $c.fil.checkRequired($c.util.getComponent('ipt_corpEngAbbrv'))) {
        return;
    }
    if (await (async (c) => { const v = String((c && c.getValue) ? (c.getValue() ?? "") : ""); const max = Number((c && c.getUserData) ? ((c.getUserData("maxByteLength") || c.getUserData("maxLength")) ?? 0) : 0) || 0; if (max && $c.str.getByteLength(v) > max) { const lbl = "영문약명"; await $c.win.alert((lbl ? ("'" + lbl + "' 항목은 ") : "") + "한글 " + (max / 2) + "자, 영문 " + max + "자까지 가능합니다."); return true; } return false; })($c.util.getComponent('ipt_corpEngAbbrv'))) {
        return;
    }
    if (await $c.fil.checkRequired($c.util.getComponent('ipt_chrgNm'))) {
        return;
    }
    if (await (async (c) => { const v = String((c && c.getValue) ? (c.getValue() ?? "") : ""); const max = Number((c && c.getUserData) ? ((c.getUserData("maxByteLength") || c.getUserData("maxLength")) ?? 0) : 0) || 0; if (max && $c.str.getByteLength(v) > max) { const lbl = "공시담당자 이름"; await $c.win.alert((lbl ? ("'" + lbl + "' 항목은 ") : "") + "한글 " + (max / 2) + "자, 영문 " + max + "자까지 가능합니다."); return true; } return false; })($c.util.getComponent('ipt_chrgNm'))) {
        return;
    }
    if (await $c.fil.checkRequired($c.util.getComponent('ipt_jobtitlNm'))) {
        return;
    }
    if (await (async (c) => { const v = String((c && c.getValue) ? (c.getValue() ?? "") : ""); const max = Number((c && c.getUserData) ? ((c.getUserData("maxByteLength") || c.getUserData("maxLength")) ?? 0) : 0) || 0; if (max && $c.str.getByteLength(v) > max) { const lbl = "직위"; await $c.win.alert((lbl ? ("'" + lbl + "' 항목은 ") : "") + "한글 " + (max / 2) + "자, 영문 " + max + "자까지 가능합니다."); return true; } return false; })($c.util.getComponent('ipt_jobtitlNm'))) {
        return;
    }
    if (await $c.fil.checkRequired($c.util.getComponent('ipt_depNm'))) {
        return;
    }
    if (await (async (c) => { const v = String((c && c.getValue) ? (c.getValue() ?? "") : ""); const max = Number((c && c.getUserData) ? ((c.getUserData("maxByteLength") || c.getUserData("maxLength")) ?? 0) : 0) || 0; if (max && $c.str.getByteLength(v) > max) { const lbl = "부서"; await $c.win.alert((lbl ? ("'" + lbl + "' 항목은 ") : "") + "한글 " + (max / 2) + "자, 영문 " + max + "자까지 가능합니다."); return true; } return false; })($c.util.getComponent('ipt_depNm'))) {
        return;
    }
    if (await $c.fil.checkRequired($c.util.getComponent('ipt_telNo1')) || await $c.fil.checkRequired($c.util.getComponent('ipt_telNo2')) || await $c.fil.checkRequired($c.util.getComponent('ipt_telNo3'))) {
        return;
    }
    if (!($c.fil.isNumberInput($c.util.getComponent('ipt_telNo1')) && $c.fil.isNumberInput($c.util.getComponent('ipt_telNo2')) && $c.fil.isNumberInput($c.util.getComponent('ipt_telNo3')))) {
        await $c.win.alert('유선전화번호는 숫자만 입력하세요');
        return;
    }
    if (!($c.fil.isNumberInput($c.util.getComponent('ipt_submitprnInnrNo')))) {
        await $c.win.alert('내선은 숫자만 입력하세요');
        return;
    }
    if (await $c.fil.checkRequired($c.util.getComponent('slc_cellphoneNo1')) || await $c.fil.checkRequired($c.util.getComponent('ipt_cellphoneNo2')) || await $c.fil.checkRequired($c.util.getComponent('ipt_cellphoneNo3'))) {
        return;
    }
    if (!($c.fil.isNumberInput($c.util.getComponent('slc_cellphoneNo1')) && $c.fil.isNumberInput($c.util.getComponent('ipt_cellphoneNo2')) && $c.fil.isNumberInput($c.util.getComponent('ipt_cellphoneNo3')))) {
        await $c.win.alert('휴대전화번호는 숫자만 입력하세요');
        return;
    }
    if (await $c.fil.checkRequired($c.util.getComponent('ipt_faxNo1')) || await $c.fil.checkRequired($c.util.getComponent('ipt_faxNo2')) || await $c.fil.checkRequired($c.util.getComponent('ipt_faxNo3'))) {
        return;
    }
    if (!($c.fil.isNumberInput($c.util.getComponent('ipt_faxNo1')) && $c.fil.isNumberInput($c.util.getComponent('ipt_faxNo2')) && $c.fil.isNumberInput($c.util.getComponent('ipt_faxNo3')))) {
        await $c.win.alert('FAX는 숫자만 입력하세요');
        return;
    }
    if (await $c.fil.checkRequired($c.util.getComponent('ipt_email1')) || await $c.fil.checkRequired($c.util.getComponent('ipt_email2'))) {
        return;
    }
    if (await $c.fil.checkRequired($c.util.getComponent('ipt_birthYear')) || await $c.fil.checkRequired($c.util.getComponent('ipt_birthMonth')) || await $c.fil.checkRequired($c.util.getComponent('ipt_birthDay'))) {
        return;
    }
    if (!await $c.fil.checkDateParts($c.util.getComponent('ipt_birthYear'), $c.util.getComponent('ipt_birthMonth'), $c.util.getComponent('ipt_birthDay'), false)) {
        return;
    }
    $c.util.getComponent('dma_ApplyJoinReq').set('telNo', $c.util.getComponent('ipt_telNo1').getValue()+ '-' + $c.util.getComponent('ipt_telNo2').getValue()+ '-' + $c.util.getComponent('ipt_telNo3').getValue());
    $c.util.getComponent('dma_ApplyJoinReq').set('cellphoneNo', $c.util.getComponent('slc_cellphoneNo1').getValue()+ '-' + $c.util.getComponent('ipt_cellphoneNo2').getValue()+ '-' + $c.util.getComponent('ipt_cellphoneNo3').getValue());
    $c.util.getComponent('dma_ApplyJoinReq').set('faxNo', $c.util.getComponent('ipt_faxNo1').getValue()+ '-' + $c.util.getComponent('ipt_faxNo2').getValue()+ '-' + $c.util.getComponent('ipt_faxNo3').getValue());
    $c.util.getComponent('dma_ApplyJoinReq').set('email', $c.str.trim($c.util.getComponent('ipt_email1').getValue()) + '@' + $c.str.trim($c.util.getComponent('ipt_email2').getValue()));
    $c.util.getComponent('dma_ApplyJoinReq').set('birthdd', $c.util.getComponent('ipt_birthYear').getValue()+ $c.util.getComponent('ipt_birthMonth').getValue()+ $c.util.getComponent('ipt_birthDay').getValue());
    if (!$c.str.isEmail($c.util.getComponent('dma_ApplyJoinReq').get('email'))) {
        return;
    }
    $c.util.getComponent('dma_ApplyJoinReq').set('method', 'registerVotedisclsSubmitprn');
    const nr = await scwin.tx_fn_ApplyJoin('votediscls.do');
    if (nr && nr.responseJSON && nr.responseJSON.success === true) {
        $c.win.moveUrl("/message/message.xml", { "method": 'registerVotedisclsSubmitprn' });
    }
};

/**
 * @method
 * @name checkPersonal
 * @description check Personal 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkPersonal = async function () {
    const personalChk = $c.util.getComponent('ipt_personalCheck').getValue();
    if (personalChk !== 'Y') {
        if (await $c.win.confirm("개인정보 처리방침 및 수집·이용에 동의해주시기 바랍니다.")) {
            (Promise.resolve($c.win.openPopup("/personalInfo_layer/personalInfo_layer.xml", { id: "personalInfo", width: "800", height: "700", scrollbars: false, type: "pageFramePopup" }, {})).then(function () {}), { closed: false, focus: function () {}, close: function () { $c.win.getScope().closePopup("personalInfo"); this.closed = true; } });
        } else {
            return;
        }
    }
};
